insert into public.categories (id, slug, name, description) values
('camisas', 'camisas', 'Camisas', 'Camisas y blusas de lino, algodón y satén para el día a día.'),
('camisetas', 'camisetas', 'Camisetas', 'Franelas, camisetas básicas y tops de punto.'),
('vestidos', 'vestidos', 'Vestidos', 'Vestidos cortos, midi y largos en telas frescas.'),
('pantalones', 'pantalones', 'Pantalones', 'Pantalones de vestir, cargo y jean con cortes cómodos.'),
('faldas', 'faldas', 'Faldas', 'Faldas midi, plisadas y de lino para combinar todo el año.'),
('chaquetas', 'chaquetas', 'Chaquetas', 'Chaquetas ligeras de denim y lino para las noches frescas.')
insert into public.products (id, slug, name, category_id, description, composition, care, price_cents, image_url, image_alt, active, created_at) values
('camisa-lino-margarita', 'camisa-lino-margarita', 'Camisa de lino Margarita', 'camisas', 'Camisa fresca de lino para el calor de la costa. Corte recto y manga larga recogible.', '55 % lino, 45 % algodón.', 'Lavar a mano con agua fría. Secar a la sombra. Planchar a temperatura media.', 2800, '/images/products/placeholder.svg', 'Camisa de lino Margarita: imagen de referencia de la prenda', true, '2026-08-03T14:00:00.000Z'),
('camisa-oversize-catuaro', 'camisa-oversize-catuaro', 'Camisa oversize Catuaro', 'camisas', 'Camisa oversize de caída suave, pensada para usar suelta o anudada.', '100 % algodón.', 'Lavar en frío con colores similares. No usar secadora.', 3200, '/images/products/placeholder.svg', 'Camisa oversize Catuaro: imagen de referencia de la prenda', true, '2026-08-21T14:00:00.000Z'),
('blusa-satinada-caroni', 'blusa-satinada-caroni', 'Blusa satinada Caroní', 'camisas', 'Blusa de satén con cuello redondo y manga corta. Cae suelta sin pegarse.', '100 % poliéster satinado.', 'Lavar a mano con agua fría. Planchar a baja temperatura.', 2600, '/images/products/placeholder.svg', 'Blusa satinada Caroní: imagen de referencia de la prenda', true, '2026-09-08T14:00:00.000Z'),
('camisa-cuadros-andes', 'camisa-cuadros-andes', 'Camisa de cuadros Andes', 'camisas', 'Camisa de cuadros en algodón ligero, corte relajado y bolsillo frontal.', '100 % algodón.', 'Lavar en frío. Secar a la sombra. Planchar a temperatura media.', 3000, '/images/products/placeholder.svg', 'Camisa de cuadros Andes: imagen de referencia de la prenda', true, '2026-09-15T14:00:00.000Z'),
('franela-pique-coro', 'franela-pique-coro', 'Franela piqué Coro', 'camisetas', 'Franela de piqué con cuello camisero. Básico de todos los días.', '95 % algodón, 5 % elastano.', 'Lavar a máquina en ciclo suave. Secar a la sombra.', 2200, '/images/products/placeholder.svg', 'Franela piqué Coro: imagen de referencia de la prenda', true, '2026-09-02T14:00:00.000Z'),
('camiseta-basica-pampatar', 'camiseta-basica-pampatar', 'Camiseta básica Pampatar', 'camisetas', 'Camiseta de algodón peinado, cuello redondo y corte recto.', '100 % algodón peinado.', 'Lavar a máquina en frío con colores similares.', 1400, '/images/products/placeholder.svg', 'Camiseta básica Pampatar: imagen de referencia de la prenda', true, '2026-07-20T14:00:00.000Z'),
('top-punto-lecheria', 'top-punto-lecheria', 'Top de punto Lechería', 'camisetas', 'Top de punto acanalado con tirantes finos y escote cuadrado.', '92 % algodón, 8 % elastano.', 'Lavar a mano. Secar en plano.', 1800, '/images/products/placeholder.svg', 'Top de punto Lechería: imagen de referencia de la prenda', true, '2026-08-30T14:00:00.000Z'),
('vestido-midi-canaima', 'vestido-midi-canaima', 'Vestido midi Canaima', 'vestidos', 'Vestido midi con cintura marcada y falda fluida.', '70 % viscosa, 30 % lino.', 'Lavar a mano. No retorcer. Planchar del revés.', 3800, '/images/products/placeholder.svg', 'Vestido midi Canaima: imagen de referencia de la prenda', true, '2026-08-12T14:00:00.000Z'),
('vestido-corto-paraguana', 'vestido-corto-paraguana', 'Vestido corto Paraguaná', 'vestidos', 'Vestido corto de tirantes ajustables para el día a día.', '100 % viscosa.', 'Lavar a mano con agua fría. Secar en plano.', 3400, '/images/products/placeholder.svg', 'Vestido corto Paraguaná: imagen de referencia de la prenda', true, '2026-09-10T14:00:00.000Z'),
('vestido-lino-isla', 'vestido-lino-isla', 'Vestido de lino Isla', 'vestidos', 'Vestido largo de lino, escote cuadrado y bolsillos laterales. Agotado por ahora.', '100 % lino.', 'Lavar a mano. Planchar húmedo.', 4200, '/images/products/placeholder.svg', 'Vestido de lino Isla: imagen de referencia de la prenda', true, '2026-07-15T14:00:00.000Z'),
('vestido-camisero-cumarebo', 'vestido-camisero-cumarebo', 'Vestido camisero Cumarebo', 'vestidos', 'Vestido camisero de lino con cinturón, botones y bolsillos.', '70 % lino, 30 % viscosa.', 'Lavar a mano. Planchar húmedo.', 4000, '/images/products/placeholder.svg', 'Vestido camisero Cumarebo: imagen de referencia de la prenda', true, '2026-09-22T14:00:00.000Z'),
('pantalon-palazzo-merida', 'pantalon-palazzo-merida', 'Pantalón palazzo Mérida', 'pantalones', 'Pantalón palazzo de cintura alta y pierna ancha.', '100 % poliéster.', 'Lavar a máquina en frío. Colgar para secar.', 3000, '/images/products/placeholder.svg', 'Pantalón palazzo Mérida: imagen de referencia de la prenda', true, '2026-08-28T14:00:00.000Z'),
('pantalon-cargo-caracas', 'pantalon-cargo-caracas', 'Pantalón cargo Caracas', 'pantalones', 'Pantalón cargo con bolsillos laterales y puños ajustables.', '98 % algodón, 2 % elastano.', 'Lavar del revés. No usar blanqueador.', 3600, '/images/products/placeholder.svg', 'Pantalón cargo Caracas: imagen de referencia de la prenda', true, '2026-09-18T14:00:00.000Z'),
('jean-recto-maracaibo', 'jean-recto-maracaibo', 'Jean recto Maracaibo', 'pantalones', 'Jean de tiro alto y pierna recta, con poco elastano.', '99 % algodón, 1 % elastano.', 'Lavar en frío del revés. Secar a la sombra.', 4000, '/images/products/placeholder.svg', 'Jean recto Maracaibo: imagen de referencia de la prenda', true, '2026-09-25T14:00:00.000Z'),
('pantalon-sastre-barquisimeto', 'pantalon-sastre-barquisimeto', 'Pantalón sastre Barquisimeto', 'pantalones', 'Pantalón sastre de pinza frontal y pierna recta.', '68 % poliéster, 30 % viscosa, 2 % elastano.', 'Lavar en frío. Colgar para secar.', 3800, '/images/products/placeholder.svg', 'Pantalón sastre Barquisimeto: imagen de referencia de la prenda', true, '2026-09-05T14:00:00.000Z'),
('pantalon-wide-leg-valencia', 'pantalon-wide-leg-valencia', 'Pantalón wide leg Valencia', 'pantalones', 'Pantalón wide leg de lino. Fuera de temporada por ahora.', '100 % lino.', 'Lavar a mano.', 3300, '/images/products/placeholder.svg', 'Pantalón wide leg Valencia: imagen de referencia de la prenda', false, '2026-06-30T14:00:00.000Z'),
('falda-midi-tucacas', 'falda-midi-tucacas', 'Falda midi Tucacas', 'faldas', 'Falda midi de cintura alta con abertura lateral.', '100 % viscosa.', 'Lavar a mano con agua fría. Secar en plano.', 3200, '/images/products/placeholder.svg', 'Falda midi Tucacas: imagen de referencia de la prenda', true, '2026-08-18T14:00:00.000Z'),
('falda-plisada-porlamar', 'falda-plisada-porlamar', 'Falda plisada Porlamar', 'faldas', 'Falda plisada de vuelo suave y elástico en la cintura.', '100 % poliéster.', 'Lavar a mano. No planchar los pliegues.', 3400, '/images/products/placeholder.svg', 'Falda plisada Porlamar: imagen de referencia de la prenda', true, '2026-09-12T14:00:00.000Z'),
('falda-lino-macuto', 'falda-lino-macuto', 'Falda de lino Macuto', 'faldas', 'Falda de lino con cintura elástica y bolsillos laterales.', '100 % lino.', 'Lavar a mano. Planchar húmedo.', 3000, '/images/products/placeholder.svg', 'Falda de lino Macuto: imagen de referencia de la prenda', true, '2026-07-28T14:00:00.000Z'),
('chaqueta-denim-la-guaira', 'chaqueta-denim-la-guaira', 'Chaqueta denim La Guaira', 'chaquetas', 'Chaqueta de denim rígido, corte oversize y bolsillos frontales.', '100 % algodón.', 'Lavar en frío del revés. Secar a la sombra.', 4800, '/images/products/placeholder.svg', 'Chaqueta denim La Guaira: imagen de referencia de la prenda', true, '2026-08-08T14:00:00.000Z'),
('chaqueta-lino-choroni', 'chaqueta-lino-choroni', 'Chaqueta de lino Choroní', 'chaquetas', 'Chaqueta ligera de lino para las noches frescas.', '100 % lino.', 'Lavar a mano. Planchar del revés.', 4500, '/images/products/placeholder.svg', 'Chaqueta de lino Choroní: imagen de referencia de la prenda', true, '2026-09-20T14:00:00.000Z')
